// Un tokenizer très simplifié (les vrais tokenizers sont plus subtils : sous-mots, pas juste des mots)
function tokenizeApprox(texte) {
  return texte
    .toLowerCase()
    .match(/[a-zàâäéèêëïîôöùûü]+|[^\s]/g) || [];
}

const phrase = "Les tokens ne sont pas des mots entiers.";
const tokens = tokenizeApprox(phrase);

console.log("Phrase :", phrase);
console.log("Nombre de mots :", phrase.split(' ').length);
console.log("Nombre de tokens (approx.) :", tokens.length);
console.log(tokens);

